const createElement = (tag, className) => Object.assign(document.createElement(tag), { className });

const ORBIT_VARIANTS = Object.freeze({
  chase: { duration: 960, delays: [0, 120, 240, 360, 480, 600, 720, 840] },
  oppose: { duration: 1100, delays: [0, 120, 240, 360, 0, 120, 240, 360] },
  breathe: { duration: 1500, delays: [0, 0, 0, 0, 0, 0, 0, 0] }
});

function OrbitIndicator({ variant = "chase" } = {}) {
  const root = createElement("span", "orbit-indicator");
  root.setAttribute("aria-hidden", "true");

  const nodes = Array.from({ length: 8 }, (_, index) => {
    const node = createElement("span", "orbit-node");
    const dot = createElement("span", "orbit-dot");
    node.dataset.orbitIndex = index;
    node.style.setProperty("--orbit-angle", `${index * 45}deg`);
    node.append(dot);
    root.append(node);
    return dot;
  });

  function setVariant(nextVariant) {
    const normalizedVariant = ORBIT_VARIANTS[nextVariant] ? nextVariant : "chase";
    const pattern = ORBIT_VARIANTS[normalizedVariant];
    root.dataset.variant = normalizedVariant;
    nodes.forEach((dot, index) => {
      dot.style.setProperty("--orbit-duration", `${pattern.duration}ms`);
      dot.style.setProperty("--orbit-delay", `${pattern.delays[index]}ms`);
    });
  }

  setVariant(variant);
  return { root, setVariant };
}

const BEACON_VARIANTS = Object.freeze({
  rise: { duration: 980, delays: [0, 90, 180, 270, 360] },
  fall: { duration: 980, delays: [360, 270, 180, 90, 0] },
  balance: { duration: 1180, delays: [0, 180, 360, 180, 0] }
});

function BeaconIndicator({ variant = "rise" } = {}) {
  const root = createElement("span", "beacon-indicator");
  root.setAttribute("aria-hidden", "true");
  const bars = Array.from({ length: 5 }, (_, index) => {
    const bar = createElement("span", "beacon-indicator__bar rhythm-motion-unit");
    bar.style.setProperty("--beacon-height", `${7 + Math.abs(2 - index) * 2}px`);
    root.append(bar);
    return bar;
  });

  function setVariant(nextVariant) {
    const normalized = BEACON_VARIANTS[nextVariant] ? nextVariant : "rise";
    const pattern = BEACON_VARIANTS[normalized];
    root.dataset.variant = normalized;
    bars.forEach((bar, index) => {
      bar.style.setProperty("--rhythm-duration", `${pattern.duration}ms`);
      bar.style.setProperty("--rhythm-delay", `${pattern.delays[index]}ms`);
    });
  }

  setVariant(variant);
  return { root, setVariant };
}

const MATRIX_VARIANTS = Object.freeze({
  diagonal: { duration: 1040, delays: [0, 90, 180, 90, 180, 270, 180, 270, 360] },
  ripple: { duration: 1160, delays: [240, 120, 240, 120, 0, 120, 240, 120, 240] },
  scan: { duration: 980, delays: [0, 0, 0, 180, 180, 180, 360, 360, 360] }
});

function MatrixIndicator({ variant = "diagonal" } = {}) {
  const root = createElement("span", "matrix-indicator");
  root.setAttribute("aria-hidden", "true");
  const dots = Array.from({ length: 9 }, () => {
    const dot = createElement("span", "matrix-indicator__dot rhythm-motion-unit");
    root.append(dot);
    return dot;
  });

  function setVariant(nextVariant) {
    const normalized = MATRIX_VARIANTS[nextVariant] ? nextVariant : "diagonal";
    const pattern = MATRIX_VARIANTS[normalized];
    root.dataset.variant = normalized;
    dots.forEach((dot, index) => {
      dot.style.setProperty("--rhythm-duration", `${pattern.duration}ms`);
      dot.style.setProperty("--rhythm-delay", `${pattern.delays[index]}ms`);
    });
  }

  setVariant(variant);
  return { root, setVariant };
}

const CELL_VARIANTS = Object.freeze({
  merge: { duration: 1120, delays: [0, 100, 200, 300] },
  spread: { duration: 1120, delays: [300, 200, 100, 0] },
  checker: { duration: 1260, delays: [0, 280, 280, 0] }
});

function CellIndicator({ variant = "merge" } = {}) {
  const root = createElement("span", "cell-indicator");
  root.setAttribute("aria-hidden", "true");
  const cells = Array.from({ length: 4 }, () => {
    const cell = createElement("span", "cell-indicator__cell rhythm-motion-unit");
    root.append(cell);
    return cell;
  });

  function setVariant(nextVariant) {
    const normalized = CELL_VARIANTS[nextVariant] ? nextVariant : "merge";
    const pattern = CELL_VARIANTS[normalized];
    root.dataset.variant = normalized;
    cells.forEach((cell, index) => {
      cell.style.setProperty("--rhythm-duration", `${pattern.duration}ms`);
      cell.style.setProperty("--rhythm-delay", `${pattern.delays[index]}ms`);
    });
  }

  setVariant(variant);
  return { root, setVariant };
}

const REGISTER_VARIANTS = Object.freeze({
  shift: { duration: 1040, delays: [0, 90, 180, 270, 360, 450] },
  invert: { duration: 1220, delays: [0, 0, 0, 260, 260, 260] },
  pair: { duration: 1320, delays: [0, 0, 220, 220, 440, 440] }
});

function RegisterIndicator({ variant = "shift" } = {}) {
  const root = createElement("span", "register-indicator");
  root.setAttribute("aria-hidden", "true");
  const bits = Array.from({ length: 6 }, (_, index) => {
    const bit = createElement("span", "register-indicator__bit rhythm-motion-unit");
    bit.dataset.bit = index % 2 === 0 ? "one" : "zero";
    root.append(bit);
    return bit;
  });

  function setVariant(nextVariant) {
    const normalized = REGISTER_VARIANTS[nextVariant] ? nextVariant : "shift";
    const pattern = REGISTER_VARIANTS[normalized];
    root.dataset.variant = normalized;
    bits.forEach((bit, index) => {
      bit.style.setProperty("--rhythm-duration", `${pattern.duration}ms`);
      bit.style.setProperty("--rhythm-delay", `${pattern.delays[index]}ms`);
    });
  }

  setVariant(variant);
  return { root, setVariant };
}

const BAND_VARIANTS = Object.freeze({
  descend: { duration: 1060, delays: [0, 180, 360] },
  ascend: { duration: 1060, delays: [360, 180, 0] },
  split: { duration: 1260, delays: [0, 280, 0] }
});

function BandIndicator({ variant = "descend" } = {}) {
  const root = createElement("span", "band-indicator");
  root.setAttribute("aria-hidden", "true");
  const segments = Array.from({ length: 3 }, () => {
    const row = createElement("span", "band-indicator__row");
    const rail = createElement("span", "band-indicator__rail");
    const segment = createElement("span", "band-indicator__segment rhythm-motion-unit");
    row.append(rail, segment);
    root.append(row);
    return segment;
  });

  function setVariant(nextVariant) {
    const normalized = BAND_VARIANTS[nextVariant] ? nextVariant : "descend";
    const pattern = BAND_VARIANTS[normalized];
    root.dataset.variant = normalized;
    segments.forEach((segment, index) => {
      segment.style.setProperty("--rhythm-duration", `${pattern.duration}ms`);
      segment.style.setProperty("--rhythm-delay", `${pattern.delays[index]}ms`);
    });
  }

  setVariant(variant);
  return { root, setVariant };
}

const LIFT_QUEUE_VARIANTS = Object.freeze({
  rise: { duration: 1240, delays: [0, 120, 240, 360] },
  fall: { duration: 1240, delays: [360, 240, 120, 0] },
  breathe: { duration: 1560, delays: [0, 100, 200, 300] }
});

function LiftQueueIndicator({ variant = "rise" } = {}) {
  const root = createElement("span", "lift-queue-indicator");
  root.setAttribute("aria-hidden", "true");
  const levels = Array.from({ length: 4 }, (_, index) => {
    const level = createElement("span", "lift-queue-indicator__level rhythm-motion-unit");
    level.style.setProperty("--lift-level", index);
    root.append(level);
    return level;
  });
  function setVariant(nextVariant) {
    const normalized = LIFT_QUEUE_VARIANTS[nextVariant] ? nextVariant : "rise";
    const pattern = LIFT_QUEUE_VARIANTS[normalized];
    root.dataset.variant = normalized;
    levels.forEach((level, index) => {
      level.style.setProperty("--rhythm-duration", `${pattern.duration}ms`);
      level.style.setProperty("--rhythm-delay", `${pattern.delays[index]}ms`);
    });
  }
  setVariant(variant);
  return { root, setVariant };
}

const indicatorCSS = ".orbit-indicator {
  position: relative;
  width: 24px;
  height: 24px;
  flex: 0 0 24px;
}

.orbit-node {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 3.5px;
  height: 3.5px;
  margin-top: -1.75px;
  margin-left: -1.75px;
  transform: rotate(var(--orbit-angle)) translateY(-9px);
  transform-origin: 1.75px 1.75px;
}

.orbit-dot {
  display: block;
  width: 3.5px;
  height: 3.5px;
  border-radius: 999px;
  background: var(--ink);
  opacity: 0.18;
  scale: 0.72;
  animation: orbit-node var(--orbit-duration) ease-in-out var(--orbit-delay) infinite;
}

@keyframes orbit-node {
  0%, 100% {
    background-color: var(--ink);
    opacity: 0.18;
    scale: 0.72;
  }
  20% {
    background-color: var(--accent);
    opacity: 1;
    scale: 1.2;
  }
  42% {
    background-color: var(--accent);
    opacity: 0.7;
    scale: 1;
  }
  65% {
    background-color: var(--ink);
    opacity: 0.18;
    scale: 0.72;
  }
}

.orbit-indicator[data-variant="breathe"] .orbit-dot {
  animation-name: orbit-breathe;
}

@keyframes orbit-breathe {
  0%, 100% {
    background-color: var(--ink);
    opacity: 0.25;
    scale: 0.82;
  }
  50% {
    background-color: var(--accent);
    opacity: 0.82;
    scale: 1.08;
  }
}

.beacon-indicator,
.matrix-indicator {
  position: relative;
  width: 24px;
  height: 24px;
  flex: 0 0 24px;
}

.beacon-indicator {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 2px;
}

.beacon-indicator__bar {
  width: 2px;
  height: var(--beacon-height);
  border-radius: 1px;
  background: var(--ink);
  opacity: 0.22;
  scale: 1 0.56;
  animation: beacon-bar var(--rhythm-duration) cubic-bezier(0.45, 0, 0.25, 1) var(--rhythm-delay) infinite;
}

@keyframes beacon-bar {
  0%, 100% { opacity: 0.22; scale: 1 0.56; }
  28% { opacity: 0.52; scale: 1 0.82; }
  48% { opacity: 1; scale: 1 1; }
  72% { opacity: 0.34; scale: 1 0.68; }
}

.beacon-indicator[data-variant="balance"] .beacon-indicator__bar {
  animation-name: beacon-balance;
}

@keyframes beacon-balance {
  0%, 100% { opacity: 0.24; scale: 1 0.62; }
  50% { opacity: 0.94; scale: 1 1; }
}

.matrix-indicator {
  display: grid;
  grid-template-columns: repeat(3, 3px);
  grid-auto-rows: 3px;
  place-content: center;
  gap: 3px;
}

.matrix-indicator__dot {
  width: 3px;
  height: 3px;
  border-radius: 999px;
  background: var(--ink);
  opacity: 0.2;
  scale: 0.68;
  animation: matrix-node var(--rhythm-duration) cubic-bezier(0.45, 0, 0.25, 1) var(--rhythm-delay) infinite;
}

@keyframes matrix-node {
  0%, 100% { opacity: 0.2; scale: 0.68; }
  30% { opacity: 0.46; scale: 0.82; }
  48% { opacity: 1; scale: 1.18; }
  72% { opacity: 0.3; scale: 0.74; }
}

.matrix-indicator[data-variant="ripple"] .matrix-indicator__dot {
  animation-name: matrix-ripple;
}

@keyframes matrix-ripple {
  0%, 100% { opacity: 0.18; scale: 0.64; }
  42% { opacity: 0.94; scale: 1.12; }
  68% { opacity: 0.36; scale: 0.78; }
}

.matrix-indicator[data-variant="scan"] .matrix-indicator__dot {
  border-radius: 1px;
  animation-name: matrix-scan;
}

@keyframes matrix-scan {
  0%, 100% { opacity: 0.18; scale: 0.72; }
  34%, 56% { opacity: 1; scale: 1; }
  76% { opacity: 0.32; scale: 0.76; }
}

.band-indicator {
  position: relative;
  width: 24px;
  height: 24px;
  flex: 0 0 24px;
}

.band-indicator {
  display: grid;
  align-content: center;
  gap: 4px;
}

.band-indicator__row {
  position: relative;
  display: block;
  width: 20px;
  height: 2px;
  margin-inline: auto;
  overflow: hidden;
  border-radius: 1px;
}

.band-indicator__rail,
.band-indicator__segment {
  position: absolute;
  inset: 0;
  display: block;
}

.band-indicator__rail {
  background: var(--line-strong);
}

.band-indicator__segment {
  width: 7px;
  border-radius: 1px;
  background: var(--ink);
  opacity: 0.26;
  translate: -8px 0;
  animation: band-segment var(--rhythm-duration) cubic-bezier(0.45, 0, 0.25, 1) var(--rhythm-delay) infinite;
}

@keyframes band-segment {
  0%, 100% { opacity: 0.2; translate: -8px 0; }
  42% { opacity: 1; translate: 7px 0; }
  70% { opacity: 0.36; translate: 14px 0; }
}

.band-indicator[data-variant="ascend"] .band-indicator__segment {
  animation-name: band-return;
}

@keyframes band-return {
  0%, 100% { opacity: 0.2; translate: 21px 0; }
  42% { opacity: 1; translate: 7px 0; }
  70% { opacity: 0.36; translate: -8px 0; }
}

.band-indicator[data-variant="split"] .band-indicator__row:nth-child(odd) .band-indicator__segment {
  animation-name: band-split-forward;
}

.band-indicator[data-variant="split"] .band-indicator__row:nth-child(even) .band-indicator__segment {
  animation-name: band-split-reverse;
}

@keyframes band-split-forward {
  0%, 100% { opacity: 0.24; translate: 6px 0; scale: 0.42 1; }
  46%, 64% { opacity: 1; translate: 13px 0; scale: 1 1; }
}

@keyframes band-split-reverse {
  0%, 100% { opacity: 0.24; translate: 7px 0; scale: 0.42 1; }
  46%, 64% { opacity: 1; translate: 0 0; scale: 1 1; }
}

.cell-indicator {
  position: relative;
  width: 24px;
  height: 24px;
  flex: 0 0 24px;
}

.cell-indicator {
  display: grid;
  grid-template-columns: repeat(2, 6px);
  grid-auto-rows: 6px;
  place-content: center;
  gap: 3px;
}

.cell-indicator__cell {
  width: 6px;
  height: 6px;
  border-radius: 1.5px;
  background: var(--ink);
  opacity: 0.2;
  scale: 0.7;
  animation: cell-merge var(--rhythm-duration) cubic-bezier(0.45, 0, 0.25, 1) var(--rhythm-delay) infinite;
}

.cell-indicator__cell:nth-child(1) { --cell-x: 2px; --cell-y: 2px; }

.cell-indicator__cell:nth-child(2) { --cell-x: -2px; --cell-y: 2px; }

.cell-indicator__cell:nth-child(3) { --cell-x: 2px; --cell-y: -2px; }

.cell-indicator__cell:nth-child(4) { --cell-x: -2px; --cell-y: -2px; }

@keyframes cell-merge {
  0%, 100% { opacity: 0.2; scale: 0.7; translate: 0 0; }
  44%, 62% { opacity: 1; scale: 1; translate: var(--cell-x) var(--cell-y); }
  78% { opacity: 0.36; scale: 0.78; translate: 0 0; }
}

.cell-indicator[data-variant="spread"] .cell-indicator__cell {
  animation-name: cell-spread;
}

@keyframes cell-spread {
  0%, 100% { opacity: 0.24; scale: 0.76; translate: var(--cell-x) var(--cell-y); }
  46%, 64% { opacity: 1; scale: 1; translate: 0 0; }
  80% { opacity: 0.4; scale: 0.82; translate: var(--cell-x) var(--cell-y); }
}

.cell-indicator[data-variant="checker"] .cell-indicator__cell {
  animation-name: cell-checker;
}

@keyframes cell-checker {
  0%, 100% { opacity: 0.2; scale: 0.68; }
  42%, 64% { opacity: 1; scale: 1; }
  80% { opacity: 0.34; scale: 0.76; }
}

.register-indicator {
  position: relative;
  width: 24px;
  height: 24px;
  flex: 0 0 24px;
}

.register-indicator {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 2px;
}

.register-indicator__bit {
  display: block;
  width: 2px;
  height: 9px;
  border-radius: 1px;
  background: var(--ink);
  opacity: 0.2;
  scale: 1 0.42;
  animation: register-shift var(--rhythm-duration) cubic-bezier(0.45, 0, 0.25, 1) var(--rhythm-delay) infinite;
}

.register-indicator__bit[data-bit="zero"] {
  translate: 0 3px;
}

.register-indicator__bit[data-bit="one"] {
  translate: 0 -3px;
}

@keyframes register-shift {
  0%, 100% { opacity: 0.2; scale: 1 0.42; }
  32% { opacity: 0.5; scale: 1 0.72; }
  50% { opacity: 1; scale: 1 1; }
  74% { opacity: 0.32; scale: 1 0.52; }
}

.register-indicator[data-variant="invert"] .register-indicator__bit {
  animation-name: register-invert;
}

@keyframes register-invert {
  0%, 100% { opacity: 0.2; scale: 1 0.42; }
  44%, 64% { opacity: 1; scale: 1 1; }
  80% { opacity: 0.36; scale: 1 0.54; }
}

.register-indicator[data-variant="pair"] .register-indicator__bit {
  animation-name: register-pair;
}

@keyframes register-pair {
  0%, 100% { opacity: 0.22; scale: 1 0.44; }
  40%, 62% { opacity: 0.96; scale: 1 0.92; }
  78% { opacity: 0.34; scale: 1 0.52; }
}

.lift-queue-indicator {
  position: relative;
  width: 24px;
  height: 24px;
  flex: 0 0 24px;
}

.lift-queue-indicator::before {
  position: absolute;
  top: 3px;
  bottom: 3px;
  left: 11.5px;
  width: 1px;
  background: var(--line-strong);
  content: "";
}

.lift-queue-indicator__level {
  position: absolute;
  bottom: calc(3px + var(--lift-level) * 5px);
  left: calc(9px - var(--lift-level) * .65px);
  width: calc(6px + var(--lift-level) * 1.3px);
  height: 3px;
  border-radius: 1.5px;
  background: var(--ink);
  opacity: .18;
  transform-origin: center;
  animation: lift-queue-rise var(--rhythm-duration) cubic-bezier(.34, 1.4, .55, 1) var(--rhythm-delay) infinite;
}

@keyframes lift-queue-rise {
  0%, 100% { opacity: .16; translate: 0 2px; scale: .72; }
  32% { opacity: .5; translate: 0 0; scale: .9; }
  50% { opacity: 1; translate: 0 -2px; scale: 1.08; }
  74% { opacity: .3; translate: 0 -3px; scale: .82; }
}

.lift-queue-indicator[data-variant="fall"] .lift-queue-indicator__level {
  animation-name: lift-queue-fall;
}

@keyframes lift-queue-fall {
  0%, 100% { opacity: .14; translate: 0 -2px; scale: .72; }
  34% { opacity: .54; translate: 0 0; scale: .9; }
  52% { opacity: 1; translate: 0 2px; scale: 1.08; }
  76% { opacity: .28; translate: 0 3px; scale: .8; }
}

.lift-queue-indicator[data-variant="breathe"] .lift-queue-indicator__level {
  animation-name: lift-queue-breathe;
}

@keyframes lift-queue-breathe {
  0%, 100% { opacity: .22; scale: .72 1; }
  50% { opacity: .92; scale: 1 1; }
}

@keyframes orbit-spin { to { rotate: 360deg; } }

@keyframes orbit-elastic { 0%, 100% { scale: 1.25; } 50% { scale: .75; } }

@keyframes beacon-sway { 0%, 100% { transform: translate(-2px, 1px) scale(.85); } 50% { transform: translate(2px, -1px) scale(1.2); } }

@keyframes cell-main-flow {
  0% { opacity: 0; transform: translate(0, 0); }
  10% { opacity: 1; }
  44% { opacity: 1; transform: translate(0, 14px); }
  52%, 60% { opacity: 1; transform: translate(0, 20px); }
  70% { opacity: 0; transform: translate(0, 22px); }
  100% { opacity: 0; transform: translate(0, 0); }
}

@keyframes cell-sort-lane {
  0%, 42% { opacity: 0; transform: translate(0, 0); }
  46% { opacity: 1; transform: translate(0, 14px); }
  58% { opacity: 1; transform: translate(-12px, 17px); }
  66% { opacity: 1; transform: translate(-18px, 14px); }
  76% { opacity: 0; transform: translate(-20px, 14px); }
  100% { opacity: 0; transform: translate(-18px, 14px); }
}

@keyframes cell-outlet-pulse {
  0%, 66% { opacity: 0; transform: scale(.5); }
  74%, 84% { opacity: 1; transform: scale(1.25); }
  94%, 100% { opacity: 0; transform: scale(1.5); }
}

@keyframes cell-pass-pulse {
  0%, 60% { opacity: 0; transform: scale(.5); }
  68%, 80% { opacity: 1; transform: scale(1.25); }
